VALUES
  ('lib-lb-01', 'קמר-קער (חתול-פרה)', 'גב תחתון', 'back_lower', 2, 15, NULL, 1, 'clinical', 'עמידת שש. קמרו את הגב למעלה תוך הוצאת אוויר, ולאחר מכן קערו למטה תוך הכנסת אוויר.', 20, 'קמר קער', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 1),
  ('lib-lb-02', 'רוטציות מותניות', 'גב תחתון', 'back_lower', 2, 20, NULL, 1, 'clinical', 'שכבו על הגב, ברכיים כפופות וצמודות. הורידו את שתי הברכיים יחד מצד לצד בעדינות.', 20, 'רוטציות מותניות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 2),
  ('lib-lb-03', 'מתיחת עכוז לעקבים (Childs Pose)', 'גב תחתון', 'back_lower', 2, NULL, 45, 1, 'standard', 'מעמידת שש, הורידו ישבן לאחור לעבר העקבים. מתחו ידיים קדימה ונשמו עמוק.', 20, 'מתיחת עכוז לעקבים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 3),
  ('lib-lb-04', 'ברך יחידה לחזה', 'גב תחתון', 'back_lower', 2, NULL, 30, 1, 'clinical', 'שכבו על הגב, רגל אחת ישרה. משכו את הברך השנייה אל החזה והחזיקו.', 20, 'ברך לחזה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 4),
  ('lib-lb-05', 'שתי ברכיים לחזה', 'גב תחתון', 'back_lower', 2, NULL, 30, 1, 'clinical', 'שכבו על הגב. משכו את שתי הברכיים יחד אל החזה כדי לרווח את חוליות המותן.', 20, 'שתי ברכיים לחזה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 5),
  ('lib-lb-06', 'אקסטנציה בשכיבה (Cobra)', 'גב תחתון', 'back_lower', 2, 10, NULL, 2, 'clinical', 'שכבו על הבטן. בעזרת הידיים דחפו והרימו רק את פלג הגוף העליון. האגן נשאר צמוד למזרן.', 25, 'אקסטנציה בשכיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 6),
  ('lib-lb-07', 'הטיית אגן צדית (Pelvic Hike)', 'גב תחתון', 'back_lower', 2, 15, NULL, 1, 'clinical', 'שכבו על הגב עם רגליים ישרות. נסו "לקצר" רגל אחת על ידי משיכת האגן בצד זה לכיוון הצלעות.', 20, 'הטיית אגן צדית', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 7),
  ('lib-lb-08', 'מתיחת פריפורמיס בשכיבה', 'גב תחתון', 'back_lower', 2, NULL, 45, 2, 'standard', 'שכבו על הגב. הניחו קרסול אחד על הברך השנייה (צורת 4) ומשכו את הירך אליכם.', 25, 'מתיחת פריפורמיס', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 8),
  ('lib-lb-09', 'כיפוף גב בישיבה', 'גב תחתון', 'back_lower', 2, NULL, 30, 1, 'clinical', 'שבו על כיסא, פסקו רגליים. התכופפו קדימה והניחו לידיים ולראש להישמט בין הרגליים.', 20, 'כיפוף בישיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 9),
  ('lib-lb-10', 'החלקת עצב סכיאטי - Slump', 'גב תחתון', 'back_lower', 2, 12, NULL, 2, 'clinical', 'שבו שפופים. יישרו ברך ובו זמנית הרימו ראש. כופפו ברך והורידו ראש חזרה. (תנועה רציפה).', 30, 'Slump Glide', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 10),
  ('lib-lb-11', 'החלקת עצב סכיאטי - בשכיבה', 'גב תחתון', 'back_lower', 2, 12, NULL, 2, 'clinical', 'שכבו על הגב, אחזו ירך אחת ב-90 מעלות. יישרו את הברך ומשכו אצבעות רגל אליכם (פלקס), ושחררו.', 30, 'Supine Sciatic Glide', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 11),
  ('lib-lb-12', 'הטיית אגן לאחור (Posterior Tilt)', 'גב תחתון', 'back_lower', 3, 15, NULL, 1, 'standard', 'שכבו על הגב. אספו בטן התחתונה ולחצו את כל הגב התחתון למזרן. שחררו לאט.', 20, 'הטיית אגן לאחור', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 12),
  ('lib-lb-13', 'גיוס שריר ה-TrA', 'ליבה', 'back_lower', 3, 10, 10, 2, 'clinical', 'שכבו על הגב. "שאבו" את הפופיק בעדינות פנימה ולמעלה מבלי לעצור נשימה או להזיז את האגן.', 25, 'גיוס TrA', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 13),
  ('lib-lb-14', 'גשר אגן בסיסי', 'גב תחתון', 'back_lower', 3, 12, NULL, 2, 'clinical', 'שכבו על הגב, ברכיים כפופות. כווצו ישבן והרימו אגן עד קו ישר מהברך לכתף.', 30, 'גשר אגן בסיסי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 14),
  ('lib-lb-15', 'גשר אגן עם צעידה', 'ליבה', 'back_lower', 3, 10, NULL, 3, 'clinical', 'בצעו גשר אגן. כשהאגן באוויר, נתקו רגל אחת מעט מהרצפה, הניחו והחליפו, מבלי שהאגן יצנח.', 40, 'גשר עם צעידה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 15),
  ('lib-lb-16', 'חרק מת - שלב 1 (רגליים)', 'ליבה', 'back_lower', 3, 12, NULL, 2, 'clinical', 'שכבו על הגב, רגליים ב-90 באוויר. געו עם עקב אחד ברצפה והחזירו, הגב התחתון צמוד למזרן.', 30, 'חרק מת שלב 1', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 16),
  ('lib-lb-17', 'חרק מת - שלב 2 (מלא)', 'ליבה', 'back_lower', 3, 10, NULL, 3, 'clinical', 'ידיים ורגליים באוויר. הורידו במקביל יד ורגל נגדית. אל תאפשרו לגב התחתון להתקשת.', 40, 'חרק מת שלב 2', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 17),
  ('lib-lb-18', 'ציפור-כלב - שלב 1', 'ליבה', 'back_lower', 3, 12, NULL, 2, 'clinical', 'עמידת שש. החליקו והרימו רק רגל אחת בכל פעם לאחור, תוך שמירה על גב ישר לגמרי.', 30, 'ציפור כלב רגליים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 18),
  ('lib-lb-19', 'ציפור-כלב - מלא (Bird-Dog)', 'ליבה', 'back_lower', 3, 10, NULL, 3, 'clinical', 'עמידת שש. יישרו יד ורגל נגדית יחד. החזיקו 2 שניות והחליפו מבלי לסובב את האגן.', 40, 'ציפור כלב מלא', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 19),
  ('lib-lb-20', 'ייצוב אגן - צדפות (Clamshells)', 'גב תחתון', 'back_lower', 3, 15, NULL, 2, 'clinical', 'שכבו על הצד, ברכיים כפופות יחד. פתחו את הברך העליונה כלפי מעלה מבלי לסובב את האגן לאחור.', 30, 'צדפות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 20),
  ('lib-lb-21', 'פלאנק על ברכיים', 'ליבה', 'back_lower', 3, NULL, 30, 2, 'standard', 'הישענו על אמות הידיים והברכיים. כווצו בטן וישבן בקו אלכסוני ישר.', 30, 'פלאנק ברכיים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 21),
  ('lib-lb-22', 'פלאנק מלא', 'ליבה', 'back_lower', 3, NULL, 30, 4, 'standard', 'פלאנק על אמות וקצות האצבעות ברגליים. גוף ישר כמו קרש. למנוע קריסת אגן.', 45, 'פלאנק מלא', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 22),
  ('lib-lb-23', 'פלאנק צדי על ברכיים', 'ליבה', 'back_lower', 3, NULL, 20, 3, 'clinical', 'שכבו על הצד על האמה, ברכיים כפופות. הרימו אגן עד קו ישר מהברך לראש.', 35, 'פלאנק צדי ברכיים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 23),
  ('lib-lb-24', 'פלאנק צדי מלא', 'ליבה', 'back_lower', 3, NULL, 20, 5, 'standard', 'הישענו על אמה וצד כף הרגל. הרימו אגן. שמרו על צוואר בהמשך לגוף.', 50, 'פלאנק צדי מלא', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 24),
  ('lib-lb-25', 'גשר אגן רגל אחת', 'גב תחתון', 'back_lower', 3, 10, NULL, 4, 'clinical', 'שכבו על הגב, רגל אחת ישרה באוויר. בעזרת הרגל השנייה, דחפו והרימו את האגן.', 45, 'גשר רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 25),
  ('lib-lb-26', 'לחיצת פאלופ (Pallof Press)', 'ליבה', 'back_lower', 3, 12, NULL, 4, 'clinical', 'עמדו לצד גומייה קשורה. משכו אותה לחזה, ויישרו ידיים קדימה. התנגדו למשיכה הצידה.', 40, 'לחיצת פאלופ', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 26),
  ('lib-lb-27', 'שחייה יבשה (Superman)', 'גב תחתון', 'back_lower', 3, 12, NULL, 3, 'clinical', 'שכבו על הבטן. הרימו בו זמנית יד ורגל נגדית (או את כל הגפיים יחד) והורידו.', 35, 'סופרמן', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 27),
  ('lib-lb-28', 'הליכת איכר (משקולת אחת)', 'ליבה', 'back_lower', 3, NULL, 40, 4, 'standard', 'החזיקו משקולת/בקבוק מים ביד אחת בלבד ולכו זקוף. אל תתנו למשקל למשוך אתכם הצידה.', 45, 'הליכת איכר צד 1', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 28),
  ('lib-lb-29', 'קראנצ'' מותאם (McGill Curl-up)', 'ליבה', 'back_lower', 3, 10, NULL, 2, 'clinical', 'שכבו על הגב, רגל אחת כפופה, ידיים מתחת לגב התחתון. הרימו ראש וכתפיים כיחידה אחת רק מעט מהרצפה.', 30, 'קראנץ מותאם', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 29),
  ('lib-lb-30', 'רוטציה נגד התנגדות (Woodchop)', 'ליבה', 'back_lower', 3, 12, NULL, 4, 'standard', 'בעזרת גומייה המקובעת גבוה, משכו אותה באלכסון כלפי מטה אל הברך הנגדית תוך סיבוב מבוקר של הגו.', 45, 'Woodchop', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 30),
  ('lib-kn-01', 'החלקת עקב (Heel Slides)', 'ברך', 'knee_right', 3, 15, NULL, 1, 'clinical', 'שכבו על הגב. החליקו את העקב לכיוון הישבן עד לתחושת מתיחה קלה, ויישרו חזרה מבוקר.', 20, 'החלקת עקב', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 31),
  ('lib-kn-02', 'החלקת עקב בעזרת מגבת', 'ברך', 'knee_right', 3, 5, 10, 2, 'clinical', 'שכבו על הגב. הניחו מגבת סביב כף הרגל ובעזרת הידיים משכו את העקב לישבן להגדלת טווח הכיפוף.', 25, 'החלקת עקב עם מגבת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 32),
  ('lib-kn-03', 'יישור פסיבי בשכיבה (Prone Hang)', 'ברך', 'knee_right', 2, NULL, 60, 1, 'clinical', 'שכבו על הבטן בקצה המיטה כך שהברכיים מחוץ למיטה באוויר. תנו לכוח המשיכה ליישר את הברך אט אט.', 20, 'Prone Hang', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 33),
  ('lib-kn-04', 'מתיחת ארבע ראשי עמידה', 'ברך', 'knee_right', 2, NULL, 30, 2, 'standard', 'עמדו בתמיכת קיר. תפסו את הקרסול מאחור ומשכו את העקב לישבן עד למתיחה בקדמת הירך.', 20, 'מתיחת ארבע ראשי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 34),
  ('lib-kn-05', 'כיווץ סטטי ארבע-ראשי (Quad Sets)', 'ברך', 'knee_right', 3, 5, 15, 1, 'clinical', 'שבו בשיכול רגליים או שכיבה. לחצו את גב הברך חזק אל המזרן על ידי כיווץ הירך הקדמית, החזיקו 15 שניות ושחררו לאט.', 25, 'לחיצת ברך', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 35),
  ('lib-kn-06', 'כיווץ המסטרינגס סטטי', 'ברך', 'knee_right', 3, 5, 15, 1, 'clinical', 'שבו כשהברך כפופה מעט. לחצו את העקב חזק לתוך הרצפה מבלי להזיז את הרגל, כדי לכווץ את הירך האחורית. החזיקו 15 שניות ושחררו.', 25, 'כיווץ המסטרינגס סטטי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 36),
  ('lib-kn-07', 'יישור ברך מקוצר (SAQ)', 'ברך', 'knee_right', 3, 15, NULL, 2, 'clinical', 'שימו מגבת מגולגלת תחת הברך. הרימו רק את העקב באוויר עד ליישור מלא של הברך, החזיקו שנייה והורידו.', 30, 'SAQ', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 37),
  ('lib-kn-08', 'יישור ברך מלא בישיבה (LAQ)', 'ברך', 'knee_right', 3, 12, NULL, 2, 'standard', 'שבו על כיסא. הרימו את כף הרגל ויישרו את הברך במלואה מול כוח המשיכה. ירידה איטית.', 30, 'LAQ', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 38),
  ('lib-kn-09', 'הרמת רגל ישרה לפנים (SLR)', 'ברך', 'knee_right', 3, 12, NULL, 2, 'clinical', 'שכבו על הגב. רגל אחת כפופה. נעלו את הברך השנייה והרימו את הרגל ישרה עד גובה הברך הכפופה.', 35, 'SLR', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 39),
  ('lib-kn-10', 'הרמת רגל ישרה הצידה (SLR Abd)', 'ברך', 'knee_right', 3, 12, NULL, 2, 'clinical', 'שכבו על הצד הבריא. הרימו את הרגל העליונה (הפגועה) ישרה כלפי מעלה לאחור קלות. ירידה מבוקרת.', 35, 'SLR אבדוקציה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 40),
  ('lib-kn-11', 'הרמת רגל ישרה לאחור (SLR Ext)', 'ברך', 'knee_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הבטן. הרימו את הרגל ישרה באוויר בעזרת שרירי הישבן והירך האחורית מבלי להקשית את הגב.', 35, 'SLR אקסטנציה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 41),
  ('lib-kn-12', 'כיפוף ברך בשכיבה', 'ברך', 'knee_right', 3, 15, NULL, 2, 'standard', 'שכבו על הבטן. כופפו את הברך והביאו את העקב לכיוון הישבן נגד כוח המשיכה. הורידו לאט.', 30, 'כיפוף ברך בטן', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 42),
  ('lib-kn-13', 'כיפוף ברך בעמידה', 'ברך', 'knee_right', 3, 15, NULL, 2, 'standard', 'עמדו זקוף בתמיכת כיסא. כופפו ברך אחת לאחור (עקב לישבן) תוך שמירה על ירכיים מקבילות.', 30, 'כיפוף ברך עמידה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 43),
  ('lib-kn-14', 'יישור ברך בעמידה (TKE)', 'ברך', 'knee_right', 3, 15, NULL, 2, 'clinical', 'קשרו גומייה מאחורי הברך ולעמוד. כופפו מעט את הברך ויישרו אותה חזק כנגד התנגדות הגומייה (נעילת ברך).', 35, 'TKE', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 44),
  ('lib-kn-15', 'קימה מכיסא (Sit to Stand)', 'ברך', 'knee_right', 3, 12, NULL, 2, 'standard', 'שבו על כיסא. קומו לעמידה בעזרת שתי הרגליים (שליטה שווה) ושבו חזרה לאט מבלי "ליפול" לכיסא.', 35, 'קימה מכיסא', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 45),
  ('lib-kn-16', 'מיני סקווט (כריעה 45°)', 'ברך', 'knee_right', 3, 15, NULL, 3, 'clinical', 'עמידת מוצא. כופפו ברכיים רק עד 45°. וודאו שהברכיים מופנות לאצבעות השנייה-שלישית ולא קורסות פנימה.', 40, 'מיני סקווט', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 46),
  ('lib-kn-17', 'סקווט מלא', 'ברך', 'knee_right', 3, 12, NULL, 4, 'standard', 'סקווט רגיל עד 90 מעלות. משקל על העקבים, חזה מורם וברכיים בקו האצבעות.', 45, 'סקווט מלא', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 47),
  ('lib-kn-18', 'ישיבת קיר סטטית (Wall Sit)', 'ברך', 'knee_right', 3, NULL, 30, 3, 'clinical', 'הישענו על הקיר ורדו לזווית של 60-90 מעלות. שמרו על הגב צמוד והחזיקו את התנוחה סטטית (איזומטרי).', 40, 'ישיבת קיר', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 48),
  ('lib-kn-19', 'עלייה על מדרגה קדמית (Step Up)', 'ברך', 'knee_right', 3, 12, NULL, 4, 'clinical', 'עמדו מול מדרגה. עלו עם הרגל הפגועה תוך דחיפה חזקה. ירדו לאט עם שליטה על הברך.', 45, 'עלייה קדמית למדרגה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 49),
  ('lib-kn-20', 'עלייה מדרגה צדית (Lateral Step Up)', 'ברך', 'knee_right', 3, 12, NULL, 4, 'clinical', 'עמדו לצד מדרגה. עלו הצידה עם הרגל הקרובה למדרגה. מקדו את העבודה בישבן הצדי ובארבע הראשי.', 45, 'עלייה צדית', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 50),
  ('lib-kn-21', 'ירידה ממדרגה (Eccentric Step Down)', 'ברך', 'knee_right', 3, 10, NULL, 5, 'clinical', 'עמדו על מדרגה. הורידו אט אט את העקב של הרגל הבריאה לרצפה על ידי כיפוף איטי ומבוקר של הרגל הפגועה.', 50, 'ירידה אקסנטרית ממדרגה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 51),
  ('lib-kn-22', 'מכרע קדמי (Lunge)', 'ברך', 'knee_right', 3, 10, NULL, 4, 'standard', 'קחו צעד גדול קדימה. כופפו את שתי הברכיים ל-90 מעלות (האחורית כמעט נוגעת ברצפה) ודחפו חזרה.', 45, 'לאנג קדמי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 52),
  ('lib-kn-23', 'מכרע אחורי (Reverse Lunge)', 'ברך', 'knee_right', 3, 10, NULL, 4, 'clinical', 'צעדו לאחור עם רגל אחת ורדו למכרע. מצוין להפחתת לחץ על הפיקה בהשוואה למכרע קדמי.', 45, 'לאנג אחורי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 53),
  ('lib-kn-24', 'עמידה על רגל אחת', 'ברך', 'knee_right', 3, NULL, 30, 3, 'clinical', 'עמדו על הרגל הפגועה בלבד (הברך לא נעולה לגמרי, מעט משוחררת). שמרו על יציבות האגן.', 35, 'עמידה רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 54),
  ('lib-kn-25', 'עמידה על רגל אחת - עיניים עצומות', 'ברך', 'knee_right', 3, NULL, 20, 4, 'clinical', 'עמדו על הרגל הפגועה ועיצמו עיניים. עמדו בפינת חדר או סמוך לכיסא לבטיחות למקרה של איבוד שיווי משקל.', 45, 'רגל אחת עיניים עצומות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 55),
  ('lib-kn-26', 'דדליפט רגל אחת (Arabesque)', 'ברך', 'knee_right', 3, 10, NULL, 4, 'clinical', 'עמדו על הרגל הפגועה. התכופפו קדימה מהאגן תוך הרמת הרגל האחורית ישרה. שמרו על גב ישר לגמרי.', 45, 'דדליפט רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 56),
  ('lib-kn-27', 'הושטת רגל כוכב (Star / Y-Balance)', 'ברך', 'knee_right', 3, 5, NULL, 5, 'clinical', 'עמדו על הרגל הפגועה. הושיטו את הרגל השנייה רחוק קדימה, הצידה, ולאחור באלכסון. אל תניחו משקל על הרגל המושטת.', 50, 'Y-Balance', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 57),
  ('lib-kn-28', 'נחיתה מקפיצה (Drop Landing)', 'ברך', 'knee_right', 3, 8, NULL, 5, 'clinical', 'רדו ממדרגה קטנה (לא קפיצה!) ונחתו רך על שתי רגליים. המטרה: כיפוף ברכיים וספיגת זעזוע ללא קריסת ברך פנימה.', 50, 'נחיתה ממדרגה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 58),
  ('lib-kn-29', 'קפיצות קלות במקום (Pogo Hops)', 'ברך', 'knee_right', 3, NULL, 20, 4, 'standard', 'קפיצות קלות ומהירות על שתי רגליים במקום. העבודה בעיקר מהקרסוליים עם ברכיים "רכות".', 45, 'Pogo Hops', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 59),
  ('lib-kn-30', 'קפיצות צד (Skater Jumps)', 'ברך', 'knee_right', 3, 16, NULL, 5, 'standard', 'קפצו מצד לצד (מרגל לרגל), ונחתו בצורה מבוקרת ויציבה על הרגל הקולטת. שמרו על שיווי משקל לשנייה לפני הקפיצה הבאה.', 50, 'קפיצות צד החלקה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 60),
  ('lib-hp-01', 'מתיחת מכופפי ירך (Kneeling Hip Flexor)', 'ירך', 'hip_right', 2, NULL, 45, 2, 'clinical', 'עמדו בעמידת פסיעה (ברך אחת על הרצפה). קחו את האגן מעט קדימה תוך כיווץ הישבן עד לתחושת מתיחה בקדמת הירך התחתונה.', 25, 'מתיחת מכופפי ירך', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 61),
  ('lib-hp-02', 'מתיחת פרפר (מפשעה)', 'ירך', 'hip_right', 2, NULL, 45, 1, 'standard', 'שבו עם גב זקוף, הצמידו כפות רגליים זו לזו. בעזרת המרפקים, דחפו בעדינות את הברכיים לכיוון הרצפה.', 20, 'מתיחת פרפר', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 62),
  ('lib-hp-03', 'מתיחת פריפורמיס (צורת 4)', 'ירך', 'hip_right', 2, NULL, 45, 2, 'standard', 'שכבו על הגב. הניחו קרסול של הרגל הפגועה על הברך השנייה. משכו את הירך הבריאה לכיוון החזה.', 25, 'מתיחת פריפורמיס', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 63),
  ('lib-hp-04', 'ישיבת 90/90 (רוטציות ירך)', 'ירך', 'hip_right', 2, 10, NULL, 3, 'clinical', 'שבו על הרצפה כששתי הברכיים כפופות ל-90 מעלות ומונחות על הרצפה (אחת קדימה, אחת הצידה). הישענו קדימה ואז החליפו צדדים.', 30, 'ישיבת 90/90', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 64),
  ('lib-hp-05', 'הרחקת ירך אקטיבית בשכיבה', 'ירך', 'hip_right', 3, 15, NULL, 1, 'clinical', 'שכבו על הגב, רגליים ישרות. החליקו רגל אחת הצידה (הרחקה) והחזירו לאמצע, ללא סיבוב של האגן.', 20, 'הרחקת ירך שכיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 65),
  ('lib-hp-06', 'כיווץ ישבן סטטי (Glute Sets)', 'ירך', 'hip_right', 3, 5, 15, 1, 'clinical', 'שכבו על הגב או הבטן. כווצו את שרירי הישבן חזק ככל האפשר, החזיקו 15 שניות ושחררו.', 20, 'כיווץ ישבן', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 66),
  ('lib-hp-07', 'לחיצת כדור בין הברכיים (Adductor Squeeze)', 'ירך', 'hip_right', 3, 5, 15, 1, 'clinical', 'שכבו על הגב, ברכיים כפופות. הניחו כדור קטן או כרית בין הברכיים ולחצו פנימה (קירוב ירכיים). החזיקו 15 שניות ושחררו.', 25, 'לחיצת מקרבים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 67),
  ('lib-hp-08', 'צדפות (Clamshells)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הצד, ברכיים כפופות. פתחו את הברך העליונה (כמו צדפה) מבלי לקחת את האגן לאחור. הירידה איטית.', 30, 'צדפות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 68),
  ('lib-hp-09', 'צדפות הפוכות (Reverse Clamshells)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הצד, ברכיים כפופות. השאירו ברכיים צמודות והרימו רק את כף הרגל העליונה לתקרה (רוטציה פנימית).', 30, 'צדפות הפוכות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 69),
  ('lib-hp-10', 'הרמת רגל ישרה הצידה (SLR Abduction)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הצד, הרגל העליונה ישרה. הרימו אותה מעלה ומעט לאחור (לכיוון העקב). הימנעו מלפנות עם האצבעות לתקרה.', 35, 'SLR הצידה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 70),
  ('lib-hp-11', 'הרמת רגל פנימה (SLR Adduction)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הצד. הניחו את הרגל העליונה כפופה מלפנים, והרימו את הרגל התחתונה ישרה כלפי מעלה.', 30, 'SLR מקרבים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 71),
  ('lib-hp-12', 'פשיטת ירך בשכיבה על הבטן', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הבטן. כווצו ישבן והרימו רגל ישרה באוויר. אל תתנו לגב התחתון להתקשת יתר על המידה.', 30, 'פשיטת ירך שכיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 72),
  ('lib-hp-13', 'הרחקת ירך בעמידת שש (Fire Hydrants)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'עמידת שש. הרימו ברך אחת הצידה החוצה תוך שמירה על זווית 90 מעלות. אגן מקביל לרצפה.', 35, 'Fire Hydrant', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 73),
  ('lib-hp-14', 'בעיטת חמור (Donkey Kicks)', 'ירך', 'hip_right', 3, 15, NULL, 2, 'clinical', 'עמידת שש. דחפו עקב אחד כלפי התקרה (פשיטת ירך) מבלי להקשית את הגב התחתון. כווצו ישבן בשיא התנועה.', 35, 'בעיטת חמור', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 74),
  ('lib-hp-15', 'הרחקת ירך בעמידה עם גומייה', 'ירך', 'hip_right', 3, 12, NULL, 3, 'clinical', 'קשרו גומייה סביב הקרסוליים. עמדו זקוף והרחיקו רגל אחת הצידה מבלי להישען עם הגוף לכיוון הנגדי.', 40, 'הרחקה בעמידה גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 75),
  ('lib-hp-16', 'פשיטת ירך בעמידה עם גומייה', 'ירך', 'hip_right', 3, 12, NULL, 3, 'clinical', 'גומייה סביב הקרסוליים. משכו רגל אחת ישרה לאחור בעזרת הישבן בלבד. שמרו על בטן אסופה למניעת הקשתת גב.', 40, 'פשיטה בעמידה גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 76),
  ('lib-hp-17', 'כפיפת ירך בעמידה עם גומייה', 'ירך', 'hip_right', 3, 12, NULL, 3, 'standard', 'גומייה סביב הקרסוליים (אפשר לקבע לקיר). הרימו את הברך הפגועה מעלה לפנים עד זווית 90 מעלות.', 40, 'כפיפת ירך בעמידה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 77),
  ('lib-hp-18', 'גשר אגן עם רצועת התנגדות', 'ירך', 'hip_right', 3, 15, NULL, 3, 'clinical', 'שכבו על הגב, גומייה מעל הברכיים. בצעו גשר אגן רגיל, ובשיא הגובה דחפו את הברכיים החוצה כנגד הגומייה.', 40, 'גשר אגן גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 78),
  ('lib-hp-19', 'דחיפת אגן (Hip Thrust)', 'ירך', 'hip_right', 3, 12, NULL, 4, 'standard', 'הישענו עם השכמות על ספסל/ספה, רגליים על הרצפה. הורידו אגן ודחפו חזק למעלה בעזרת הישבן עד קו ישר.', 45, 'היפ טראסט', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 79),
  ('lib-hp-20', 'הליכת סרטן צדדית (Lateral Band Walks)', 'ירך', 'hip_right', 3, 15, NULL, 3, 'clinical', 'גומייה מעל הברכיים או קרסוליים. רדו לחצי סקווט (Athletic stance). צעדו הצידה בצעדים קטנים ללא "קפיצות".', 40, 'הליכת סרטן', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 80),
  ('lib-hp-21', 'הליכת מפלצת (Monster Walks)', 'ירך', 'hip_right', 3, 15, NULL, 3, 'clinical', 'גומייה סביב הקרסוליים. צעדו קדימה ואחורה בצעדים רחבים באלכסון (כמו מפלצת) תוך שמירה על ברכיים החוצה.', 40, 'הליכת מפלצת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 81),
  ('lib-hp-22', 'ציר ירך (Hip Hinge / RDL)', 'ירך', 'hip_right', 3, 12, NULL, 3, 'clinical', 'עמדו עם מקל על הגב (ראש, שכמות, אגן צמודים). דחפו ישבן רחוק לאחור עם כיפוף קל בברכיים. קומו חזרה מדחיפת אגן.', 40, 'היפ הינג', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 82),
  ('lib-hp-23', 'דדליפט רגל אחת (Single Leg RDL)', 'ירך', 'hip_right', 3, 10, NULL, 4, 'clinical', 'עמדו על רגל אחת. בצעו ציר ירך: הטו את הגו קדימה והרימו את הרגל האחורית ישרה באוויר. אגן נשאר מקביל לרצפה.', 45, 'RDL רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 83),
  ('lib-hp-24', 'מכרע צדי (Lateral Lunge)', 'ירך', 'hip_right', 3, 12, NULL, 4, 'standard', 'קחו צעד רחב הצידה. כופפו את הברך הפוסעת ודחפו ישבן לאחור (הרגל השנייה נשארת ישרה). דחפו חזרה למרכז.', 45, 'לאנג צדי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 84),
  ('lib-hp-25', 'מכרע לאחור (Reverse Lunge)', 'ירך', 'hip_right', 3, 12, NULL, 4, 'clinical', 'צעדו צעד גדול לאחור ורדו למכרע (זווית 90 מעלות בברכיים). הדחיפה חזרה למעלה מתבצעת מהרגל הקדמית ומהישבן.', 45, 'לאנג אחורי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 85),
  ('lib-hp-26', 'צניחת אגן (Pelvic Drops)', 'ירך', 'hip_right', 3, 15, NULL, 4, 'clinical', 'עמדו על מדרגה כשרגל אחת תלויה באוויר. הורידו את האגן התלוי למטה (בלי לכופף את הברך העומדת), והרימו חזרה בעזרת הישבן של הרגל העומדת.', 45, 'צניחת אגן על מדרגה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 86),
  ('lib-hp-27', 'עלייה גבוהה למדרגה (High Step Up)', 'ירך', 'hip_right', 3, 10, NULL, 4, 'standard', 'השתמשו במדרגה גבוהה מהרגיל. עלו בעזרת הרגל הפגועה תוך הטיית גו קלה קדימה להפעלת מקסימלית של הישבן.', 50, 'עלייה גבוהה למדרגה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 87),
  ('lib-hp-28', 'פסיעות רוחב מורחבות (Crossover Steps)', 'ירך', 'hip_right', 3, 12, NULL, 4, 'standard', 'הליכה צדדית שבה רגל אחת מצליבה מלפנים (קרוס-אובר) או מאחור לרגל העומדת. עבודה מצוינת על פיתול ושליטה באגן.', 45, 'Crossover Steps', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 88),
  ('lib-hp-29', 'הושטת רגל (Y-Balance)', 'ירך', 'hip_right', 3, 6, NULL, 5, 'clinical', 'עמדו על רגל אחת. בעזרת הרגל השנייה, נסו לגעת ברצפה רחוק ככל האפשר: קדימה, באלכסון אחורה-ימינה, ובאלכסון אחורה-שמאלה.', 50, 'Y-Balance ירך', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 89),
  ('lib-hp-30', 'קפיצות למרחק על רגל אחת (Single Leg Broad Jump)', 'ירך', 'hip_right', 3, 8, NULL, 5, 'standard', 'קפצו למרחק על הרגל הפגועה, ונסו לנחות נחיתה "רכה" ויציבה. הישאר במצב נחיתה לשנייה מלאה לפני הקפיצה הבאה.', 50, 'קפיצה רגל אחת למרחק', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 90),
  ('lib-sh-01', 'פנדולום (מטוטלת)', 'כתף', 'shoulder_right', 3, NULL, 30, 1, 'clinical', 'הישענו קדימה בתמיכת היד הבריאה. תנו לזרוע הפגועה להיות תלויה ורפויה לחלוטין. ציירו מעגלים קטנים מהאגן.', 20, 'פנדולום', 'https://sbbmyxztjmeerfmuhrka.supabase.co/storage/v1/object/public/exercise-videos/pendulum.mp4', NULL, NULL, true, 91),
  ('lib-sh-02', 'החלקת קיר עם מגבת (Wall Slide)', 'כתף', 'shoulder_right', 3, 10, NULL, 1, 'clinical', 'עמדו מול קיר עם מגבת קטנה תחת כף היד. החליקו את היד מעלה לאורך הקיר עד למתיחה, והחליקו חזרה למטה.', 25, 'החלקת קיר', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 92),
  ('lib-sh-03', 'כפיפת כתף בשכיבה עם מקל', 'כתף', 'shoulder_right', 2, 15, NULL, 1, 'clinical', 'שכבו על הגב. אחזו מקל מטאטא בשתי ידיים. בעזרת היד הבריאה, דחפו את המקל לאחור מעל הראש.', 20, 'מקל כפיפה שכיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 93),
  ('lib-sh-04', 'סיבוב חיצוני עם מקל (External Rotation)', 'כתף', 'shoulder_right', 2, 15, NULL, 1, 'clinical', 'שכבו על הגב, מרפק צמוד לגוף ב-90°. בעזרת המקל והיד הבריאה, דחפו את כף היד הפגועה החוצה.', 20, 'מקל סיבוב חיצוני', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 94),
  ('lib-sh-05', 'מתיחת קפסולה אחורית (Cross Body)', 'כתף', 'shoulder_right', 2, NULL, 30, 1, 'standard', 'הביאו את הזרוע הפגועה אופקית מעבר לחזה. בעזרת היד השנייה, משכו אותה בעדינות אליכם.', 20, 'מתיחת כתף אחורית', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 95),
  ('lib-sh-06', 'מתיחת שרוול (Sleeper Stretch)', 'כתף', 'shoulder_right', 2, NULL, 30, 2, 'clinical', 'שכבו על הצד הפגוע, מרפק ב-90° מול החזה. בעזרת היד הבריאה, דחפו את כף היד בעדינות כלפי המזרן (סיבוב פנימי).', 25, 'סליפר סטרץ', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 96),
  ('lib-sh-07', 'מתיחת חזה בפינה (Pec Stretch)', 'כתף', 'shoulder_right', 2, NULL, 30, 1, 'standard', 'עמדו בפינת חדר, הניחו אמות על הקירות (מרפקים ב-90°). הישענו בעדינות קדימה עם החזה.', 20, 'מתיחת חזה בפינה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 97),
  ('lib-sh-08', 'ספר פתוח (Open Book)', 'כתף', 'shoulder_right', 2, 10, NULL, 2, 'clinical', 'שכבו על הצד, ידיים מושטות קדימה. פתחו את היד העליונה לאחור (כמו פתיחת דף בספר) ועקבו אחריה עם המבט.', 25, 'ספר פתוח', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 98),
  ('lib-sh-09', 'איזומטרי: סיבוב חיצוני (ER) קיר', 'כתף', 'shoulder_right', 3, 10, 5, 1, 'clinical', 'עמדו לצד קיר. מרפק ב-90°. לחצו את גב כף היד אל הקיר החוצה חזק, מבלי להזיז את הגוף.', 20, 'איזומטרי סיבוב חיצוני', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 99),
  ('lib-sh-10', 'איזומטרי: סיבוב פנימי (IR) קיר', 'כתף', 'shoulder_right', 3, 10, 5, 1, 'clinical', 'עמדו מול פינה או משקוף. מרפק ב-90°. לחצו את כף היד פנימה אל הקיר ככל האפשר.', 20, 'איזומטרי סיבוב פנימי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 100),
  ('lib-sh-11', 'איזומטרי: כפיפה (Flexion) קיר', 'כתף', 'shoulder_right', 3, 10, 5, 1, 'clinical', 'עמדו פנים אל הקיר. אגרוף קפוץ מול הקיר (מרפק ב-90°). דחפו את האגרוף קדימה אל הקיר.', 20, 'איזומטרי כפיפה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 101),
  ('lib-sh-12', 'איזומטרי: הרחקה (Abduction) קיר', 'כתף', 'shoulder_right', 3, 10, 5, 1, 'clinical', 'עמדו לצד הקיר. דחפו את המרפק אל הקיר הצידה (כאילו מנסים להרים את היד באוויר).', 20, 'איזומטרי הרחקה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 102),
  ('lib-sh-13', 'קירוב שכמות (Scapular Retraction)', 'כתף', 'shoulder_right', 3, 15, NULL, 1, 'clinical', 'בישיבה או עמידה. משכו את הכתפיים לאחור וקרבו שכמות זו לזו ("צבוט עיפרון בין השכמות").', 25, 'קירוב שכמות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 103),
  ('lib-sh-14', 'סיבוב חיצוני עם גומייה (ER)', 'כתף', 'shoulder_right', 3, 15, NULL, 2, 'clinical', 'גומייה מקובעת לקיר בגובה המותן. מרפק ב-90° צמוד לגוף (אפשר מגבת בבית השחי). סובבו את האמה החוצה נגד ההתנגדות.', 30, 'סיבוב חיצוני גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 104),
  ('lib-sh-15', 'סיבוב פנימי עם גומייה (IR)', 'כתף', 'shoulder_right', 3, 15, NULL, 2, 'clinical', 'קבעו גומייה לקיר בגובה המותן. מרפק צמוד ב-90°. משכו את האמה פנימה לכיוון הבטן.', 30, 'סיבוב פנימי גומייה', 'https://sbbmyxztjmeerfmuhrka.supabase.co/storage/v1/object/public/exercise-videos/IR%20with%20teraband.mp4', NULL, NULL, true, 105),
  ('lib-sh-16', 'סיבוב חיצוני בשכיבה (Side-lying ER)', 'כתף', 'shoulder_right', 3, 12, NULL, 2, 'clinical', 'שכבו על הצד הבריא (יד פגועה למעלה). מרפק צמוד ב-90°. הרימו משקולת קלה/בקבוק כלפי מעלה מבלי לנתק מרפק.', 30, 'ER שכיבה על הצד', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 106),
  ('lib-sh-17', 'משיכת גומייה לאחור (Rows)', 'כתף', 'shoulder_right', 3, 15, NULL, 2, 'standard', 'אחזו בגומייה המקובעת מולכם. משכו את המרפקים לאחור תוך קירוב חזק של השכמות בסוף התנועה.', 30, 'חתירה עם גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 107),
  ('lib-sh-18', 'הרמה בצורת Y בשכיבה', 'כתף', 'shoulder_right', 3, 10, NULL, 3, 'clinical', 'שכבו על הבטן. הרימו את הידיים באלכסון קדימה (צורת Y), אגודלים מופנים לתקרה. כווצו שכמות תחתונה.', 35, 'Prone Y', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 108),
  ('lib-sh-19', 'הרמה בצורת T בשכיבה', 'כתף', 'shoulder_right', 3, 10, NULL, 3, 'clinical', 'שכבו על הבטן. הושיטו ידיים הצידה בקו הכתפיים (צורת T), אגודלים לתקרה. הרימו ידיים דרך קירוב שכמות.', 35, 'Prone T', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 109),
  ('lib-sh-20', 'פשיטת כתף בשכיבה', 'כתף', 'shoulder_right', 3, 15, NULL, 2, 'clinical', 'שכבו על הבטן, ידיים צמודות לצידי הגוף. הרימו את הידיים הישרות כלפי מעלה (לתקרה) והורידו לאט.', 30, 'Prone Extension', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 110),
  ('lib-sh-21', 'שכיבות סמיכה קיר + (Push up Plus)', 'כתף', 'shoulder_right', 3, 12, NULL, 2, 'clinical', 'בצעו שכיבת סמיכה מול קיר. בסיום הדחיפה, דחפו עוד קצת כך שהשכמות יתרחקו זו מזו (הפעלת סראטוס).', 35, 'פוש אפ פלוס קיר', 'https://sbbmyxztjmeerfmuhrka.supabase.co/storage/v1/object/public/exercise-videos/wall%20push%20ups.mp4', NULL, NULL, true, 111),
  ('lib-sh-22', 'הרמה במישור השכמה (Scaption)', 'כתף', 'shoulder_right', 3, 12, NULL, 3, 'clinical', 'אחזו משקולות קלות. הרימו ידיים ישרות לא קדימה ולא הצידה, אלא ב-30 מעלות קדימה (מישור השכמה) עד גובה הכתף.', 40, 'סקאפשן', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 112),
  ('lib-sh-23', 'הרמה קדמית (Front Raise)', 'כתף', 'shoulder_right', 3, 12, NULL, 2, 'standard', 'אחזו משקולות. הרימו את הידיים ישרות קדימה עד גובה הכתפיים והורידו לאט.', 30, 'הרמה קדמית משקולת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 113),
  ('lib-sh-24', 'הרמה צדית (Lateral Raise)', 'כתף', 'shoulder_right', 3, 12, NULL, 3, 'standard', 'אחזו משקולות. הרימו ידיים הצידה (עם כיפוף קל جدا במרפק) עד גובה הכתפיים. אין לעבור גובה כתף בשיקום אקוטי.', 35, 'הרמה צדית משקולת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 114),
  ('lib-sh-25', 'לחיצת כתף (Overhead Press)', 'כתף', 'shoulder_right', 3, 10, NULL, 4, 'standard', 'אחזו משקולות בגובה הכתפיים. דחפו אותן מעלה מעל הראש עד ליישור מלא והורידו מבוקר.', 45, 'לחיצת כתף מעל הראש', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 115),
  ('lib-sh-26', 'חיבוק דינמי עם גומייה (Dynamic Hug)', 'כתף', 'shoulder_right', 3, 15, NULL, 3, 'clinical', 'העבירו גומייה מאחורי הגב ואחזו בקצוות. בצעו תנועת חיבוק גדולה קדימה. מצוין לסראטוס אנטריור.', 40, 'חיבוק דינמי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 116),
  ('lib-sh-27', 'אלכסוני PNF עם גומייה (D2 Flexion)', 'כתף', 'shoulder_right', 3, 10, NULL, 4, 'clinical', 'גומייה למטה בצד הנגדי. שלפו חרב: משכו אלכסון למעלה והחוצה, תוך סיבוב היד כך שהאגודל למעלה.', 45, 'PNF D2', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 117),
  ('lib-sh-28', 'ייצוב קצבי עם כדור קיר', 'כתף', 'shoulder_right', 3, NULL, 30, 4, 'clinical', 'החזיקו כדור מול הקיר ביד אחת (מרפק כמעט ישר). ציירו איתו מעגלים קטנים או אותיות על הקיר.', 40, 'כדור על קיר', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 118),
  ('lib-sh-29', 'הליכת דוב (Bear Crawl)', 'כתף', 'shoulder_right', 3, 10, NULL, 5, 'clinical', 'עמידת שש כשהברכיים מעט באוויר. צעדו קדימה ואחורה. דורש נשיאת משקל וייצוב כתף מעולה.', 50, 'הליכת דוב', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 119),
  ('lib-sh-30', 'פלאנק עם נגיעות כתף (Shoulder Taps)', 'כתף', 'shoulder_right', 3, 16, NULL, 5, 'standard', 'עמדו בפלאנק גבוה (על כפות הידיים). העבירו משקל ליד אחת וגעו עם היד השנייה בכתף הנגדית. החליפו.', 50, 'נגיעות כתף', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 120),
  ('lib-ak-01', 'משאבות קרסול (Ankle Pumps)', 'קרסול', 'ankle_right', 3, 20, NULL, 1, 'clinical', 'שכבו או שבו. הניעו את כף הרגל למעלה (פלקס) ולמטה (פוינט) בקצב אחיד. מצוין להורדת נפיחות.', 20, 'משאבות קרסול', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 121),
  ('lib-ak-02', 'מעגלי קרסול', 'קרסול', 'ankle_right', 2, 15, NULL, 1, 'clinical', 'סובבו את הקרסול בתנועות מעגליות גדולות ואיטיות. 15 פעמים עם כיוון השעון, ו-15 נגד הכיוון.', 15, 'מעגלי קרסול', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 122),
  ('lib-ak-03', 'כתיבת אלפבית עם הקרסול', 'קרסול', 'ankle_right', 2, 1, NULL, 1, 'clinical', 'ציירו באוויר את אותיות הא"ב בעזרת הבוהן הגדולה. התנועה מגיעה רק מהקרסול ולא מהברך.', 25, 'אלפבית קרסול', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 123),
  ('lib-ak-04', 'מתיחת שוק עם מגבת', 'קרסול', 'ankle_right', 2, NULL, 45, 1, 'standard', 'שבו כשהרגל ישרה. הניחו מגבת סביב כרית כף הרגל ומשכו אליכם בעדינות עד למתיחה בשוק לאחור.', 20, 'מתיחת מגבת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 124),
  ('lib-ak-05', 'מתיחת תאומים (Gastrocnemius)', 'קרסול', 'ankle_right', 2, NULL, 45, 1, 'standard', 'עמדו מול קיר. רגל פגועה ישרה מאחור, רגל בריאה כפופה מלפנים. דחפו עקב אחורי לרצפה עד למתיחה.', 20, 'מתיחת תאומים קיר', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 125),
  ('lib-ak-06', 'מתיחת סוליה (Soleus)', 'קרסול', 'ankle_right', 2, NULL, 45, 2, 'clinical', 'כמו מתיחת תאומים, אך הפעם כופפו מעט את הברך של הרגל האחורית (הפגועה) תוך שמירת העקב ברצפה.', 25, 'מתיחת סוליה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 126),
  ('lib-ak-07', 'מתיחת פציה פלנטרית', 'קרסול', 'ankle_right', 3, NULL, 30, 1, 'clinical', 'שבו והניחו את הקרסול הפגוע על הברך הנגדית. בעזרת היד, מתחו את אצבעות הרגל לאחור (לכיוון השוק).', 20, 'מתיחת כף רגל', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 127),
  ('lib-ak-08', 'איזומטרי: איברזיה (Eversion)', 'קרסול', 'ankle_right', 3, 10, 5, 1, 'clinical', 'שבו ליד קיר/רהיט. דחפו את הצד החיצוני של כף הרגל נגד הקיר חזק, מבלי להזיז את הרגל בפועל.', 25, 'איזומטרי החוצה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 128),
  ('lib-ak-09', 'איזומטרי: אינברזיה (Inversion)', 'קרסול', 'ankle_right', 3, 10, 5, 1, 'clinical', 'הצמידו את החלק הפנימי של כף הרגל נגד קיר או רגל כיסא. דחפו פנימה חזק והחזיקו 5 שניות.', 25, 'איזומטרי פנימה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 129),
  ('lib-ak-10', 'איזומטרי: דורסיפלקסיה', 'קרסול', 'ankle_right', 3, 10, 5, 1, 'clinical', 'הניחו את רגל אחת על השנייה. נסו להרים את הרגל התחתונה למעלה (פלקס), והתנגדו עם הרגל העליונה.', 25, 'איזומטרי פלקס', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 130),
  ('lib-ak-11', 'פוינט (Plantarflexion) עם גומייה', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'clinical', 'שבו, גומייה סביב כרית כף הרגל. אחזו בקצוות ודחפו את כף הרגל קדימה (פוינט) נגד ההתנגדות.', 30, 'פוינט גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 131),
  ('lib-ak-12', 'פלקס (Dorsiflexion) עם גומייה', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'clinical', 'קבעו גומייה לחפץ כבד מולכם וכרכו סביב גב כף הרגל. משכו את כף הרגל אליכם (פלקס) ושחררו לאט.', 30, 'פלקס גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 132),
  ('lib-ak-13', 'איברזיה (הרחקה) עם גומייה', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'clinical', 'קבעו גומייה מולכם/פנימה מכם. סובבו את כף הרגל החוצה כנגד התנגדות הגומייה. התנועה מגיעה רק מהקרסול.', 35, 'איברזיה גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 133),
  ('lib-ak-14', 'אינברזיה (קירוב) עם גומייה', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'clinical', 'שיכלו רגליים או קבעו גומייה החוצה מכם. סובבו את כף הרגל פנימה נגד ההתנגדות. ירידה מבוקרת.', 35, 'אינברזיה גומייה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 134),
  ('lib-ak-15', 'איסוף מגבת (Towel Scrunches)', 'קרסול', 'ankle_right', 2, 15, NULL, 2, 'clinical', 'שבו והניחו מגבת חלקה על הרצפה. בעזרת אצבעות כף הרגל, "אספו" את המגבת אליכם וקמטו אותה.', 30, 'איסוף מגבת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 135),
  ('lib-ak-16', 'הרמת גולות באצבעות הרגליים', 'קרסול', 'ankle_right', 2, 10, NULL, 2, 'clinical', 'פזרו מספר גולות או חפצים קטנים. בעזרת אצבעות הרגליים, הרימו אותם והעבירו לכוס קטנה.', 35, 'הרמת גולות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 136),
  ('lib-ak-17', 'עליית תאומים - שתי רגליים', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'standard', 'עמדו זקוף (אפשר להיתמך קלות). עלו גבוה על קצות האצבעות, השהו שנייה ורדו לאט.', 30, 'עליית תאומים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 137),
  ('lib-ak-18', 'עליית תאומים - רגל אחת', 'קרסול', 'ankle_right', 3, 12, NULL, 4, 'standard', 'עמדו על הרגל הפגועה בלבד. עלו על קצות האצבעות הכי גבוה שאפשר, ורדו מבוקר. השתמשו בתמיכה לשיווי משקל.', 40, 'עליית תאומים רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 138),
  ('lib-ak-19', 'ירידה אקסנטרית ממדרגה', 'קרסול', 'ankle_right', 3, 12, NULL, 4, 'clinical', 'עמדו על מדרגה עם עקבים באוויר. עלו למעלה עם 2 הרגליים, נתקו רגל בריאה, ורדו לאט *רק* עם הרגל הפגועה.', 45, 'תאומים אקסנטרי', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 139),
  ('lib-ak-20', 'עליית סוליה בישיבה (Seated Calf Raise)', 'קרסול', 'ankle_right', 3, 15, NULL, 2, 'standard', 'שבו על כיסא כשהברכיים ב-90°. הניחו משקולת/לחץ על הברכיים, והרימו עקבים מהרצפה חזק.', 30, 'עליית תאומים ישיבה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 140),
  ('lib-ak-21', 'הליכת עקבים (Heel Walk)', 'קרסול', 'ankle_right', 3, NULL, 30, 3, 'clinical', 'הרימו את קדמת כף הרגל (פלקס חזק) ולכו ברחבי החדר על העקבים בלבד. מצוין לחיזוק טיביאליס אנטריור.', 35, 'הליכת עקבים', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 141),
  ('lib-ak-22', 'הליכת קצות אצבעות', 'קרסול', 'ankle_right', 3, NULL, 30, 3, 'standard', 'עלו גבוה על קצות האצבעות ולכו ברחבי החדר. אל תתנו לעקבים לרדת לרצפה לאורך כל הסט.', 35, 'הליכת קצות אצבעות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 142),
  ('lib-ak-23', 'עמידה על רגל אחת (SLS)', 'קרסול', 'ankle_right', 3, NULL, 30, 3, 'clinical', 'עמדו על הרגל הפגועה בלבד. נסו לייצב את הקרסול ולמנוע תנודות ככל האפשר.', 35, 'עמידה רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 143),
  ('lib-ak-24', 'רגל אחת - עיניים עצומות', 'קרסול', 'ankle_right', 3, NULL, 20, 4, 'clinical', 'עמדו על הרגל הפגועה ועיצמו עיניים. התרגול מעביר את עבודת הייצוב ממערכת הראייה לקרסול.', 45, 'רגל אחת עיניים עצומות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 144),
  ('lib-ak-25', 'רגל אחת על משטח לא יציב', 'קרסול', 'ankle_right', 3, NULL, 30, 4, 'clinical', 'עמדו על הרגל הפגועה מעל כרית, פיתה לשיווי משקל או בוסו. שמרו על שיווי משקל.', 45, 'רגל אחת על כרית', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 145),
  ('lib-ak-26', 'עמידת עקב-אגודל (Tandem Stance)', 'קרסול', 'ankle_right', 3, NULL, 30, 3, 'clinical', 'עמדו כשרגל אחת בדיוק לפני השנייה (עקב נוגע באגודל - כמו הליכה על חבל). הרגל הפגועה מאחור.', 35, 'עמידת חבל', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 146),
  ('lib-ak-27', 'קפיצות צד מעל קו (Line Hops Lateral)', 'קרסול', 'ankle_right', 3, NULL, 20, 4, 'standard', 'דמיינו קו על הרצפה. קפצו ב-2 רגליים מהר מצד לצד מעל הקו (זמן מגע מינימלי עם הרצפה).', 40, 'קפיצות קו צד', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 147),
  ('lib-ak-28', 'קפיצות קדימה-אחורה מעל קו', 'קרסול', 'ankle_right', 3, NULL, 20, 4, 'standard', 'קפצו ב-2 רגליים קדימה ואחורה מעל הקו הדמיוני. שמרו על קצב מהיר וברכיים "רכות".', 40, 'קפיצות קו קדימה', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 148),
  ('lib-ak-29', 'קפיצה על רגל אחת במקום (Single Leg Hops)', 'קרסול', 'ankle_right', 3, 15, NULL, 5, 'clinical', 'קפצו קפיצות קלות במקום רק על הרגל הפגועה. התמקדו בנחיתה רכה ויציבה מהקרסול והברך.', 50, 'קפיצות רגל אחת', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 149),
  ('lib-ak-30', 'ריצה בצורת 8 (Figure 8 Run)', 'קרסול', 'ankle_right', 3, 5, NULL, 5, 'standard', 'הניחו 2 כוסות במרחק 3 מטרים. רוצו ביניהן בצורת הספרה 8. מצוין להחזרת יכולת חיתוך ושינוי כיוון לקרסול.', 50, 'ריצת שמיניות', 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', NULL, NULL, true, 150)
